// Negative matrix of the test-only mTLS fixture pin (src/e2e-fixture-pin.h), on real certificates
// generated by the harness (test-e2e-pin.ps1): only the exact fixture certificate, host, port and
// status pass; everything else is refused.
#define BROWSER_E2E_FIXTURE_HOOK 1
#include "../../src/e2e-fixture-pin.h"
#include <cstdio>
#include <sstream>

static int failures = 0;
static void Check(bool ok, const char* what) { std::printf("%s %s\n", ok ? "ok  " : "FAIL", what); if (!ok) ++failures; }
static std::string Der(const std::wstring& path) { std::ifstream in(path.c_str(), std::ios::binary); std::ostringstream s; s << in.rdbuf(); return s.str(); }

int wmain(int argc, wchar_t** argv) {
    if (argc < 2) return 2;
    const std::wstring d = argv[1];
    const std::string good = Der(d + L"\\good.der"), other = Der(d + L"\\other.der"), dns = Der(d + L"\\dns.der"), two = Der(d + L"\\two.der"), nosan = Der(d + L"\\nosan.der");
    E2EFixturePin::Manifest m; m.host = L"127.0.0.1"; m.port = 18445; m.sha256 = E2EFixturePin::Sha256Hex(good); m.loaded = true;
    const double now = 2000000000, from = now - 3600, to = now + 3600; const int untrusted = COREWEBVIEW2_WEB_ERROR_STATUS_CERTIFICATE_IS_INVALID;
    using E2EFixturePin::Decide; using V = E2EFixturePin::Verdict;
    Check(!good.empty() && Decide(m, L"https://127.0.0.1:18445/compte", untrusted, good, from, to, now) == V::Allow, "the exact fixture certificate, host, port and status: allowed");
    Check(Decide(m, L"https://127.0.0.1:18445/", untrusted, other, from, to, now) == V::Refuse, "another certificate (wrong fingerprint): refused");
    Check(Decide(m, L"https://127.0.0.1:18446/", untrusted, good, from, to, now) == V::Refuse, "another port: refused");
    Check(Decide(m, L"https://localhost:18445/", untrusted, good, from, to, now) == V::Refuse && Decide(m, L"https://127.0.0.2:18445/", untrusted, good, from, to, now) == V::Refuse, "another host (name or address): refused");
    Check(Decide(m, L"http://127.0.0.1:18445/", untrusted, good, from, to, now) == V::Refuse, "not https: refused");
    Check(Decide(m, L"https://127.0.0.1:18445@evil.test/", untrusted, good, from, to, now) == V::Refuse, "userinfo trick: refused");
    Check(Decide(m, L"https://127.0.0.1:18445/", COREWEBVIEW2_WEB_ERROR_STATUS_CERTIFICATE_EXPIRED, good, from, to, now) == V::Refuse, "status expired: refused");
    Check(Decide(m, L"https://127.0.0.1:18445/", COREWEBVIEW2_WEB_ERROR_STATUS_CERTIFICATE_REVOKED, good, from, to, now) == V::Refuse, "status revoked: refused");
    Check(Decide(m, L"https://127.0.0.1:18445/", COREWEBVIEW2_WEB_ERROR_STATUS_CERTIFICATE_COMMON_NAME_IS_INCORRECT, good, from, to, now) == V::Refuse, "status wrong name: refused");
    Check(Decide(m, L"https://127.0.0.1:18445/", untrusted, good, from, to, to + 1) == V::Refuse && Decide(m, L"https://127.0.0.1:18445/", untrusted, good, from, to, from - 1) == V::Refuse, "outside the validity period: refused");
    E2EFixturePin::Manifest md = m; md.sha256 = E2EFixturePin::Sha256Hex(dns);
    Check(Decide(md, L"https://127.0.0.1:18445/", untrusted, dns, from, to, now) == V::Refuse, "SAN DNS:localhost (even pinned): refused");
    E2EFixturePin::Manifest mt = m; mt.sha256 = E2EFixturePin::Sha256Hex(two);
    Check(Decide(mt, L"https://127.0.0.1:18445/", untrusted, two, from, to, now) == V::Refuse, "SAN with an extra entry (even pinned): refused");
    E2EFixturePin::Manifest mn = m; mn.sha256 = E2EFixturePin::Sha256Hex(nosan);
    Check(!nosan.empty() && Decide(mn, L"https://127.0.0.1:18445/", untrusted, nosan, from, to, now) == V::Refuse, "no SAN (subject CN=127.0.0.1 only, even pinned): refused");
    for (const wchar_t* u : {L"HTTPS://127.0.0.1:18445/", L"https://127.0.0.1.:18445/", L"https://[::ffff:127.0.0.1]:18445/", L"https://127.0.0.1:018445/", L"https://127%2e0.0.1:18445/", L"https://127.0.0.1\\@x:18445/", L"https://0x7f.0.0.1:18445/"})
        Check(Decide(m, u, untrusted, good, from, to, now) == V::Refuse, "URI edge form refused (case, trailing dot, IPv6-mapped, leading zero, percent, backslash, hex)");
    // Vault capture coverage (cross-origin frame): an OPTIONAL second fixture port of the same host and pinned certificate.
    E2EFixturePin::Manifest m2 = m; m2.port2 = 18446;
    Check(Decide(m2, L"https://127.0.0.1:18446/login", untrusted, good, from, to, now) == V::Allow && Decide(m2, L"https://127.0.0.1:18445/", untrusted, good, from, to, now) == V::Allow, "second fixture port declared: both fixture ports allowed (same host, same pin)");
    Check(Decide(m2, L"https://127.0.0.1:18447/", untrusted, good, from, to, now) == V::Refuse && Decide(m2, L"https://localhost:18446/", untrusted, good, from, to, now) == V::Refuse && Decide(m2, L"https://127.0.0.1:18446/", untrusted, other, from, to, now) == V::Refuse, "second fixture port: any other port, host or certificate still refused");
    { const std::wstring mf = d + L"\\pin2.txt"; std::ofstream f(mf.c_str()); f << "host=127.0.0.1\nport=18445\nport2=18446\nsha256=" << m.sha256 << "\n"; f.close();
      const auto l = E2EFixturePin::Load(mf); Check(l.loaded && l.port == 18445 && l.port2 == 18446, "manifest: optional port2 read");
      std::ofstream g(mf.c_str()); g << "host=127.0.0.1\nport=18445\nport2=0446\nsha256=" << m.sha256 << "\n"; g.close(); Check(!E2EFixturePin::Load(mf).loaded, "manifest: a malformed port2 refuses the whole manifest"); }
    E2EFixturePin::Manifest none; Check(Decide(none, L"https://127.0.0.1:18445/", untrusted, good, from, to, now) == V::Refuse, "no harness manifest: refused");
    std::printf(failures ? "FAIL e2e pin: %d\n" : "PASS e2e pin: negative matrix (fingerprint, host, port, scheme, status, validity, SAN, manifest)\n", failures);
    return failures ? 1 : 0;
}
